<#
.SYNOPSIS
    AutoNAV plugin installer for Navisworks Manage 2024 / 2025 / 2026 / 2027.
.NOTES
    Re-launches itself by passing its own content as a scriptblock instead of
    a -File argument so PowerShell execution policy (AllSigned / Restricted)
    can never block it -- only -File invocations are subject to that policy.
#>

# Remove Mark-of-the-Web (Zone.Identifier) from self if present, so subsequent
# launches don't trigger the "Not Digitally Signed" prompt either.
try { Unblock-File -Path $PSCommandPath -ErrorAction SilentlyContinue } catch {}

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Host "Requesting administrator privileges..." -ForegroundColor Yellow
    # Pass the script body via -EncodedCommand so the elevated PowerShell never
    # has to load the file -- execution policy and Zone.Identifier handling are
    # both irrelevant when there is no .ps1 file to "execute".
    $body  = Get-Content -Raw -LiteralPath $PSCommandPath
    $bytes = [System.Text.Encoding]::Unicode.GetBytes($body)
    $b64   = [Convert]::ToBase64String($bytes)
    Start-Process powershell.exe -Verb RunAs -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand', $b64) | Out-Null
    exit
}

$ErrorActionPreference = 'Stop'

$addinXml = @'
<?xml version="1.0" encoding="utf-8"?>
<Addin Version="1.0">
  <CompanyName>Keith Acker</CompanyName>
  <AddInName>AutoNAV</AddInName>
  <AddInDescription>AutoNAV - Automated Design Coordination for Navisworks</AddInDescription>
  <AddInVersion>3.7.0.0</AddInVersion>
  <FullClassName>AutoNAV.PluginMain</FullClassName>
  <AssemblyFile>AutoNAV.dll</AssemblyFile>
</Addin>
'@

$payloads = @{
    '2024' = '';
    '2025' = '';
    '2026' = '';
    '2027' = '';
}

function Close-Navisworks {
    $proc = Get-Process -Name Roamer -ErrorAction SilentlyContinue
    if ($proc) {
        Write-Host "  Closing Navisworks..." -ForegroundColor Yellow
        $proc | Stop-Process -Force
        Start-Sleep -Seconds 2
    }
}

function Install-ForYear {
    param([string]$Year, [string]$Base64Dll)
    $installDir = "C:\Program Files\Autodesk\Navisworks Manage $Year"
    if (-not (Test-Path $installDir)) {
        $altDir = "C:\Program Files (x86)\Autodesk\Navisworks Manage $Year"
        if (-not (Test-Path $altDir)) {
            Write-Host ("  [--] Navisworks Manage {0} -- not installed, skipped" -f $Year) -ForegroundColor DarkGray
            return $false
        }
        $installDir = $altDir
    }
    $pluginDir = Join-Path $installDir "Plugins\AutoNAV"
    if (-not (Test-Path $pluginDir)) { New-Item -ItemType Directory -Path $pluginDir -Force | Out-Null }
    $dllPath = Join-Path $pluginDir 'AutoNAV.dll'
    $addinPath = Join-Path $pluginDir 'AutoNAV.addin'
    if ((Test-Path $dllPath) -or (Test-Path $addinPath)) {
        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $backup = Join-Path $pluginDir "Backup_$stamp"
        New-Item -ItemType Directory -Path $backup -Force | Out-Null
        if (Test-Path $dllPath)   { Copy-Item $dllPath   $backup -Force }
        if (Test-Path $addinPath) { Copy-Item $addinPath $backup -Force }
        Write-Host ("      Backup: {0}" -f $backup) -ForegroundColor DarkGray
    }
    [System.IO.File]::WriteAllBytes($dllPath, [System.Convert]::FromBase64String($Base64Dll))
    Set-Content -Path $addinPath -Value $addinXml -Encoding UTF8
    $kb = [math]::Round((Get-Item $dllPath).Length / 1KB, 1)
    Write-Host ("  [+] Navisworks Manage {0} -- installed ({1} KB) -> {2}" -f $Year, $kb, $pluginDir) -ForegroundColor Green
    return $true
}

Write-Host ""
Write-Host "===============================================================================" -ForegroundColor Cyan
Write-Host "                AutoNAV Setup  v3.7.0" -ForegroundColor Cyan
Write-Host "        Targets: Navisworks Manage 2024 / 2025 / 2026 / 2027" -ForegroundColor Cyan
Write-Host "===============================================================================" -ForegroundColor Cyan
Write-Host ""

Close-Navisworks

$installed = @()
foreach ($year in @('2024','2025','2026','2027')) {
    if (Install-ForYear -Year $year -Base64Dll $payloads[$year]) { $installed += $year }
}

Write-Host ""
Write-Host "===============================================================================" -ForegroundColor Cyan
if ($installed.Count -gt 0) {
    Write-Host (" Installed to: Navisworks Manage {0}" -f ($installed -join ', ')) -ForegroundColor Green
    Write-Host ""
    Write-Host " Launch Navisworks Manage -> Add-Ins tab -> AutoNAV"
} else {
    Write-Host " No compatible Navisworks Manage installation detected." -ForegroundColor Red
}
Write-Host "===============================================================================" -ForegroundColor Cyan
Write-Host ""
Read-Host "Press Enter to close"
